-- Schéma
create table beer_styles (
  id text primary key,
  name text not null,
  family text not null,
  origin text not null,
  abv_range text not null,
  description text not null
);

create table beers (
  id text primary key,
  name text not null,
  brewery text not null,
  country text not null,
  style_id text not null references beer_styles(id),
  abv double precision not null,
  description text not null
);

create table brewery_locations (
  brewery text primary key,
  lat double precision not null,
  lng double precision not null,
  city text not null default '',
  address text not null default ''
);

alter table beer_styles enable row level security;
alter table beers enable row level security;
alter table brewery_locations enable row level security;

create policy "Public read access" on beer_styles for select using (true);
create policy "Public read access" on beers for select using (true);
create policy "Public read access" on brewery_locations for select using (true);

