insert into beer_styles (id, name, family, origin, abv_range, description) values ('pilsner', 'Pilsner', 'lagerBasse', 'République tchèque', '4,2 – 5,4 %', 'Lager blonde et sèche, houblonnée noblement, née à Plzeň en 1842. La référence des lagers claires modernes.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('euroPaleLager', 'Pale Lager européenne', 'lagerBasse', 'Europe', '4,5 – 5,8 %', 'Lager blonde légère et facile à boire, produite à grande échelle partout en Europe, dérivée du style Pilsner mais plus neutre.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('helles', 'Munich Helles', 'lagerBasse', 'Allemagne (Bavière)', '4,7 – 5,4 %', 'Lager blonde maltée et ronde de Munich, moins amère que la Pilsner, pensée pour être bue en grande quantité.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('dunkel', 'Munich Dunkel', 'lagerBasse', 'Allemagne (Bavière)', '4,5 – 6 %', 'Lager brune maltée, notes de pain grillé et de caramel léger, sans amertume marquée.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('schwarzbier', 'Schwarzbier', 'lagerBasse', 'Allemagne', '3,8 – 5 %', 'Lager noire douce, torréfiée mais sans l''amertume d''un stout, légère en bouche malgré sa couleur.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('marzen', 'Märzen / Oktoberfest', 'lagerBasse', 'Allemagne (Bavière)', '5,6 – 6 %', 'Lager ambrée, maltée et ronde, brassée traditionnellement en mars et servie à l''Oktoberfest de Munich.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('vienna', 'Vienna Lager', 'lagerBasse', 'Autriche', '4,5 – 5,5 %', 'Lager ambrée élégante, malt légèrement toasté, amertume modérée. Ancêtre indirect de nombreuses lagers mexicaines.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('bock', 'Bock / Doppelbock', 'lagerBasse', 'Allemagne', '6,3 – 12 %', 'Lager forte et maltée, du Bock classique au Doppelbock plus corsé encore, brassée historiquement par des moines bavarois.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('americanLager', 'American / Adjunct Lager', 'lagerBasse', 'États-Unis', '4,2 – 5 %', 'Lager très légère utilisant du maïs ou du riz en complément du malt d''orge, peu amère, très rafraîchissante.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('kellerbier', 'Kellerbier / Zwickelbier', 'lagerBasse', 'Allemagne (Franconie)', '4,5 – 5,5 %', 'Lager non filtrée servie directement depuis la cave de garde, trouble, aux notes de levure et de houblon frais.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('rauchbierLager', 'Rauchbier', 'lagerBasse', 'Allemagne (Bamberg)', '4,8 – 5,4 %', 'Lager ambrée brassée avec du malt fumé au bois de hêtre, signature de la ville de Bamberg.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('balticPorter', 'Baltic Porter', 'lagerBasse', 'Europe de la Baltique', '6,5 – 9,5 %', 'Porter fort brassé en fermentation basse, hérité des échanges commerciaux entre l''Angleterre et la mer Baltique, notes de fruits secs et de réglisse.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('indiaPaleLager', 'India Pale Lager (IPL)', 'lagerBasse', 'États-Unis', '5,5 – 6,5 %', 'Lager très houblonnée, hybride moderne entre la fraîcheur d''une lager et l''intensité aromatique d''une IPA.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('paleAle', 'Pale Ale', 'aleHaute', 'Royaume-Uni', '4,5 – 6,2 %', 'Ale ambrée équilibrée entre malt et houblon, plus douce que son dérivé l''IPA.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('ipa', 'India Pale Ale (IPA)', 'aleHaute', 'Royaume-Uni / États-Unis', '5,5 – 7,5 %', 'Ale très houblonnée, à l''origine surhoublonnée pour survivre au transport vers l''Inde coloniale, aujourd''hui déclinée à l''infini (NEIPA, Double IPA, Session IPA...).');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('neipa', 'New England IPA (Hazy IPA)', 'aleHaute', 'États-Unis', '6 – 9 %', 'IPA trouble et juteuse, texture soyeuse, houblonnage massif à cru pour des arômes de fruits tropicaux sans amertume agressive.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('doubleIpa', 'Double / Imperial IPA', 'aleHaute', 'États-Unis', '7,5 – 10,5 %', 'Version renforcée de l''IPA, plus maltée, plus alcoolisée et encore plus houblonnée.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('blackIpa', 'Black IPA / Cascadian Dark Ale', 'aleHaute', 'États-Unis', '6,5 – 9 %', 'IPA noire, torréfaction discrète pour ne pas masquer le houblonnage caractéristique de l''IPA.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('sessionIpa', 'Session IPA', 'aleHaute', 'États-Unis', '3,5 – 5 %', 'Toute l''aromatique houblonnée d''une IPA, dans un degré d''alcool réduit pour une bière plus "session".');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('americanAmberAle', 'American Amber Ale', 'aleHaute', 'États-Unis', '4,5 – 6,2 %', 'Ale ambrée américaine, équilibre entre malt caramel et houblonnage franc, plus ronde qu''une Pale Ale.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('bitter', 'Bitter / ESB', 'aleHaute', 'Royaume-Uni', '3,8 – 5,8 %', 'Ale anglaise traditionnelle de pub, équilibrée, faiblement carbonatée, souvent servie en fût à température de cave.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('kolsch', 'Kölsch', 'aleHaute', 'Allemagne (Cologne)', '4,4 – 5,2 %', 'Ale fermentée à froid puis garde à la manière d''une lager, blonde, légère et délicate, protégée par une appellation limitée à Cologne.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('altbier', 'Altbier', 'aleHaute', 'Allemagne (Düsseldorf)', '4,5 – 5,2 %', 'Ale cuivrée de Düsseldorf, fermentée haute puis gardée au froid, équilibrée entre malt toasté et houblon.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('creamAle', 'Cream Ale', 'aleHaute', 'États-Unis', '4,2 – 5,6 %', 'Ale américaine légère et douce, pensée pour ressembler à une lager facile à boire.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('brownAle', 'Brown Ale', 'aleHaute', 'Royaume-Uni', '4 – 6 %', 'Ale brune aux notes de noisette et de caramel, peu amère, facile à boire.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('porter', 'Porter', 'aleHaute', 'Royaume-Uni', '4 – 6,5 %', 'Ale sombre torréfiée née à Londres au XVIIIe siècle, ancêtre du Stout, notes de chocolat et de café.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('stout', 'Stout', 'aleHaute', 'Irlande', '4 – 8 %', 'Ale noire brassée avec de l''orge torréfiée, texture crémeuse, amertume de café et de chocolat noir.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('milkStout', 'Milk Stout / Sweet Stout', 'aleHaute', 'Royaume-Uni', '4 – 6 %', 'Stout adouci par l''ajout de lactose (sucre du lait, non fermentescible), rond et légèrement sucré.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('oatmealStout', 'Oatmeal Stout', 'aleHaute', 'Royaume-Uni', '4,2 – 5,9 %', 'Stout brassé avec une part d''avoine, texture soyeuse et onctueuse.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('imperialStout', 'Imperial Stout / Russian Imperial Stout', 'aleHaute', 'Royaume-Uni / Russie', '8 – 12 %', 'Stout très fort brassé à l''origine pour supporter le voyage jusqu''à la cour impériale russe, dense et complexe.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('barleywine', 'Barleywine', 'aleHaute', 'Royaume-Uni', '8 – 12 %', 'Ale très forte et très maltée, à garder en cave, aussi complexe qu''un vin.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('scotchAle', 'Scotch Ale / Wee Heavy', 'aleHaute', 'Écosse', '6,5 – 10 %', 'Ale écossaise forte, très maltée, peu houblonnée, souvent avec une pointe de fumé.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('belgianBlonde', 'Blonde belge', 'aleHaute', 'Belgique', '6 – 7,5 %', 'Ale blonde belge ronde et épicée par la levure, sucrosité maîtrisée par une finale sèche.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('belgianDubbel', 'Dubbel', 'aleHaute', 'Belgique', '6 – 7,6 %', 'Ale brune belge d''abbaye, notes de fruits secs, de caramel et d''épices, héritée des brasseries trappistes.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('belgianTripel', 'Tripel', 'aleHaute', 'Belgique', '7,5 – 9,5 %', 'Ale blonde belge forte, sèche et épicée, trompeusement facile à boire vu son degré d''alcool.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('belgianStrongGolden', 'Strong Golden Ale', 'aleHaute', 'Belgique', '7,5 – 10,5 %', 'Ale belge forte, blonde et pétillante, très sèche en finale malgré un fort degré d''alcool.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('quadrupel', 'Quadrupel / Belgian Dark Strong Ale', 'aleHaute', 'Belgique', '9 – 14 %', 'Ale belge sombre et très forte, notes de fruits confits, de caramel brûlé et d''alcool bien intégré.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('patersbier', 'Patersbier / Abbey Single', 'aleHaute', 'Belgique', '4,5 – 6 %', 'La bière légère et peu alcoolisée que les moines trappistes se réservent au quotidien, rarement commercialisée.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('biereDeGarde', 'Bière de Garde', 'aleHaute', 'France (Nord-Pas-de-Calais)', '6 – 8,5 %', 'Ale fermière du nord de la France, ambrée et maltée, brassée traditionnellement en hiver puis gardée en cave avant l''été.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('saison', 'Saison', 'aleHaute', 'Belgique (Wallonie)', '5 – 8,5 %', 'Ale fermière belge, sèche, épicée et rafraîchissante, brassée à l''origine pour désaltérer les saisonniers agricoles.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('witbier', 'Witbier / Blanche', 'aleHaute', 'Belgique', '4,5 – 5,5 %', 'Ale de blé non filtrée, épicée à la coriandre et à l''écorce d''orange amère, trouble et désaltérante.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('weissbier', 'Weissbier / Hefeweizen', 'aleHaute', 'Allemagne (Bavière)', '4,9 – 5,6 %', 'Ale de blé bavaroise, levure caractéristique aux notes de banane et de clou de girofle.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('lambic', 'Lambic', 'spontanee', 'Belgique (Pajottenland)', '5 – 6,5 %', 'Bière fermentée spontanément par les levures et bactéries sauvages de la vallée de la Senne, acidulée et complexe.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('gueuze', 'Gueuze', 'spontanee', 'Belgique', '5 – 8 %', 'Assemblage de lambics jeunes et vieux, refermentés en bouteille, effervescent et très acidulé.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('fruitLambic', 'Lambic fruité (Kriek, Framboise...)', 'spontanee', 'Belgique', '3,5 – 7 %', 'Lambic mis à macérer sur fruits (cerise, framboise...), acidulé et fruité.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('faro', 'Faro', 'spontanee', 'Belgique', '4 – 6 %', 'Lambic jeune adouci avec du sucre candi, doux et acidulé, historiquement la bière la plus populaire de Bruxelles.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('flandersRed', 'Flanders Red / Oud Bruin', 'mixte', 'Belgique (Flandre)', '4,6 – 6,5 %', 'Ale rouge-brune vieillie en fût de bois, fermentation mixte (levure + bactéries), acidité vineuse et notes de fruits rouges.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('gose', 'Gose', 'mixte', 'Allemagne (Leipzig)', '4,2 – 4,8 %', 'Ale de blé acidulée par des bactéries lactiques, salée et relevée de coriandre, originaire de Leipzig.');
insert into beer_styles (id, name, family, origin, abv_range, description) values ('berlinerWeisse', 'Berliner Weisse', 'mixte', 'Allemagne (Berlin)', '2,8 – 3,8 %', 'Ale de blé très légère et acidulée par fermentation mixte, traditionnellement servie avec un sirop pour adoucir l''acidité.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('pilsner-urquell', 'Pilsner Urquell', 'Plzeňský Prazdroj', 'République tchèque', 'pilsner', 4.4, 'La première Pilsner au monde, brassée depuis 1842.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('bitburger', 'Bitburger', 'Bitburger', 'Allemagne', 'pilsner', 4.8, 'Pilsner allemande sèche, référence de l''Eifel.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('veltins-pilsener', 'Veltins Pilsener', 'Veltins', 'Allemagne', 'pilsner', 4.8, 'Pilsner de Sauerland, amertume franche et bien maltée.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('meteor-pils', 'Meteor Pils', 'Brasserie Meteor', 'France', 'pilsner', 4.8, 'Pilsner alsacienne brassée selon la méthode allemande.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('jupiler', 'Jupiler', 'AB InBev', 'Belgique', 'pilsner', 5.2, 'La pils la plus populaire de Belgique.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('1664', '1664', 'Kronenbourg', 'France', 'euroPaleLager', 5.5, 'Lager blonde emblématique de la brasserie alsacienne.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('heineken', 'Heineken', 'Heineken', 'Pays-Bas', 'euroPaleLager', 5.0, 'Lager néerlandaise distribuée dans plus de 190 pays.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('estrella-damm', 'Estrella Damm', 'Damm', 'Espagne', 'euroPaleLager', 4.6, 'Lager barcelonaise brassée depuis 1876.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('peroni-nastro-azzurro', 'Peroni Nastro Azzurro', 'Peroni', 'Italie', 'euroPaleLager', 5.1, 'Lager italienne premium, symbole du style milanais.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('carlsberg', 'Carlsberg', 'Carlsberg', 'Danemark', 'euroPaleLager', 5.0, 'Lager danoise brassée à Copenhague depuis 1847.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('la-cagole-blonde', 'La Cagole Blonde', 'Brasserie La Phocéenne', 'France', 'euroPaleLager', 5.5, 'Lager blonde marseillaise devenue une figure locale.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('pelforth-blonde', 'Pelforth Blonde', 'Pelforth', 'France', 'euroPaleLager', 5.8, 'Lager blonde du Nord de la France, plus corsée que la moyenne.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('1664-blanc', '1664 Blanc', 'Kronenbourg', 'France', 'euroPaleLager', 5.0, 'Lager parfumée aux agrumes, l''une des canettes les plus vendues en supermarché en France.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('skol', 'Skol', 'Skol', 'France', 'euroPaleLager', 4.2, 'Lager d''entrée de gamme très présente en canette dans les grandes surfaces.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('grolsch-premium-lager', 'Grolsch Premium Lager', 'Grolsch', 'Pays-Bas', 'euroPaleLager', 5.0, 'Lager néerlandaise reconnaissable à sa bouteille à bouchon mécanique.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('amstel', 'Amstel', 'Amstel (Heineken)', 'Pays-Bas', 'euroPaleLager', 5.0, 'Lager néerlandaise légère, un classique des rayons de supermarché.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('bavaria', 'Bavaria', 'Bavaria Brewery', 'Pays-Bas', 'euroPaleLager', 5.0, 'Lager néerlandaise économique, vendue en pack de canettes.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('san-miguel', 'San Miguel', 'San Miguel', 'Espagne', 'euroPaleLager', 5.0, 'Lager espagnole populaire, née initialement aux Philippines.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('efes-pilsen', 'Efes Pilsen', 'Efes', 'Turquie', 'euroPaleLager', 5.0, 'Lager turque la plus vendue, en canette dans le monde entier.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('zywiec', 'Żywiec', 'Grupa Żywiec', 'Pologne', 'euroPaleLager', 5.6, 'Lager polonaise emblématique, vendue en grande distribution.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('augustiner-hell', 'Augustiner Lagerbier Hell', 'Augustiner-Bräu', 'Allemagne', 'helles', 5.2, 'Un classique munichois servi dans les biergartens.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('weihenstephaner-original-helles', 'Weihenstephaner Original Helles', 'Weihenstephaner', 'Allemagne', 'helles', 5.1, 'Brassée par la plus ancienne brasserie du monde.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('tegernseer-hell', 'Tegernseer Hell', 'Herzoglich Bayerisches Brauhaus Tegernsee', 'Allemagne', 'helles', 5.2, 'Helles bavaroise très prisée dans les biergartens de Munich.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('ayinger-dunkel', 'Ayinger Altbairisch Dunkel', 'Ayinger', 'Allemagne', 'dunkel', 5.0, 'Lager brune maltée, notes de pain grillé.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('hofbrau-dunkel', 'Hofbräu Dunkel', 'Hofbräu München', 'Allemagne', 'dunkel', 5.5, 'Dunkel munichoise ronde, notes de pain et de caramel.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('koestritzer', 'Köstritzer Schwarzbier', 'Köstritzer', 'Allemagne', 'schwarzbier', 4.8, 'Lager noire légère brassée depuis 1543.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('moenchshof-schwarzbier', 'Mönchshof Schwarzbier', 'Kulmbacher', 'Allemagne', 'schwarzbier', 4.9, 'Schwarzbier de Kulmbach, douce et légèrement torréfiée.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('paulaner-oktoberfest', 'Paulaner Oktoberfest Wiesn', 'Paulaner', 'Allemagne', 'marzen', 6.0, 'La bière officielle de l''Oktoberfest de Munich.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('hacker-pschorr-oktoberfest', 'Hacker-Pschorr Oktoberfest Märzen', 'Hacker-Pschorr', 'Allemagne', 'marzen', 5.8, 'Märzen munichoise, l''une des six bières officielles de la fête.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('spaten-oktoberfestbier', 'Spaten Oktoberfestbier', 'Spaten', 'Allemagne', 'marzen', 5.9, 'Spaten a inventé le style Märzen moderne en 1872.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('sam-adams-boston-lager', 'Samuel Adams Boston Lager', 'Boston Beer Company', 'États-Unis', 'vienna', 4.9, 'Lager ambrée qui a relancé le craft beer américain.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('negra-modelo', 'Negra Modelo', 'Grupo Modelo', 'Mexique', 'vienna', 5.4, 'Lager ambrée mexicaine héritée des brasseurs viennois.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('fischer-tradition', 'Fischer Tradition', 'Brasserie Fischer', 'France', 'vienna', 6.0, 'Lager ambrée alsacienne, malt toasté et finale ronde.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('ayinger-celebrator', 'Ayinger Celebrator', 'Ayinger', 'Allemagne', 'bock', 6.7, 'Doppelbock riche et maltée, notes de fruits secs.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('einbecker-ur-bock', 'Einbecker Ur-Bock', 'Einbecker', 'Allemagne', 'bock', 6.5, 'Le Bock originel, brassé à Einbeck depuis le Moyen Âge.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('paulaner-salvator', 'Paulaner Salvator', 'Paulaner', 'Allemagne', 'bock', 7.9, 'Le Doppelbock originel des moines de Paulaner, malté et intense.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('budweiser', 'Budweiser', 'Anheuser-Busch', 'États-Unis', 'americanLager', 5.0, 'La lager américaine la plus vendue au monde.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('corona', 'Corona Extra', 'Grupo Modelo', 'Mexique', 'americanLager', 4.5, 'Lager mexicaine légère, souvent servie avec du citron.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('asahi-super-dry', 'Asahi Super Dry', 'Asahi', 'Japon', 'americanLager', 5.0, 'Lager japonaise très sèche, la référence du pays.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('tsingtao', 'Tsingtao', 'Tsingtao Brewery', 'Chine', 'americanLager', 4.7, 'Lager chinoise brassée depuis 1903 à Qingdao.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('brahma-chopp', 'Brahma Chopp', 'Ambev', 'Brésil', 'americanLager', 4.8, 'L''une des lagers les plus vendues du Brésil.');
insert into beers (id, name, brewery, country, style_id, abv, description) values ('victoria-bitter', 'Victoria Bitter', 'Carlton United Breweries', 'Australie', 'americanLager', 4.9, 'Lager australienne emblématique, malgré son nom.');
